\label{thm:rate}
For every $\kappa>1$ the limits
\[
 \rho_{\rm HB}(\kappa)=\lim_{N\to\infty}W_N(\kappa)^{1/N}=\lim_{N\to\infty}W_N^{(5)}(\kappa)^{1/N}
\]
exist, and $\rho_{\rm HB}(\kappa)$ is given by the finite algebraic prescription of
Theorem~\ref{thm:classification}. There are constants
$0<c_\kappa\le C_\kappa<\infty$ such that
\begin{equation}\label{eq:bounds}
 c_\kappa\,\rho_{\rm HB}(\kappa)^N\le W_N^{(5)}(\kappa)\le W_N(\kappa)\le C_\kappa\,\rho_{\rm HB}(\kappa)^N\quad(N\ge0).
\end{equation}
The lower bound is attained by one function in $\mathcal F_{\mu,L}(\mathbb R^5)$ and one initial
point, independent of $N$. Moreover, one function in $\mathcal F_{\mu,L}(\mathbb R^3)$ and one
initial point satisfy
\begin{equation}\label{eq:spirallower}
 \lVert x_N-x^\star\rVert\ge\frac{\rho_{\rm sp}(\kappa)^N}{\sqrt5}\,\lVert x_0-x^\star\rVert\quad(N\ge0).
\end{equation}

\label{lem:normalization}
The map $f\mapsto\psi$ is a bijection between functions in $\mathcal F_{\mu,L}$ with
minimizer $0$ and value $0$ there, and $\mathcal S$. With $e_k=x_k-x^\star$ and
$\sigma_k=\nabla\psi(e_k)$, the iteration \eqref{eq:hb} becomes
\begin{equation}\label{eq:normrec}
 e_{k+1}=Ae_k+B\sigma_k-\beta e_{k-1},\quad
 A=1+\beta-\frac{\alpha(L+\mu)}2,\quad B=\frac{\alpha(L-\mu)}2 .
\end{equation}
For Polyak's tuning $A=0$, $B=2q$ and $\beta=q^2$.

\label{thm:interpolation}
Let $\{(x_i,\sigma_i,\psi_i):i\in I\}$ be data in a real Hilbert space
containing the datum $(x_\star,\sigma_\star,\psi_\star)=(0,0,0)$ of an index
$\star\in I$. A function $\psi\in\mathcal S$ with $\nabla\psi(x_i)=\sigma_i$
and $\psi(x_i)=\psi_i$ exists if and only if, for all $i,j\in I$,
\begin{equation}\label{eq:interpolation}
 |T_{ij}|\le R_{ij},\quad
 T_{ij}=\psi_j-\psi_i-\tfrac12\langle \sigma_i+\sigma_j,x_j-x_i\rangle,\quad
 R_{ij}=\tfrac14\bigl(\lVert x_j-x_i\rVert^2-\lVert \sigma_j-\sigma_i\rVert^2\bigr).
\end{equation}

\label{def:feasible}
A pair $(\nu,C)$ is feasible at the exponent $t$ if
\begin{equation}\label{eq:feasible}
 \begin{gathered}
 |C|\le\bar g,\\
 \ell_m:=\bar a_m-\bar b_m+C\sinh mt\ge0,\quad
 \upsilon_m:=\bar a_m+\bar b_m-C\sinh mt\ge0\quad(m\ge1).
 \end{gathered}
\end{equation}
The numbers $\ell_m$ and $\upsilon_m$ are the lower and upper lag-$m$ slacks.

\label{lem:spectralinterp}
For the orthogonal sum of waves with spectrum $\nu$ at the exponent $t$ and
function values $\psi_k=\frac14\bigl(C+2\int\operatorname{Re} m\,d\nu\bigr)e^{2kt}$,
\begin{equation}\label{eq:waveslacks}
 R_{j,j+m}\pm T_{j,j+m}=\tfrac12e^{(2j+m)t}\bigl(\bar a_m\mp\bar b_m\pm C\sinh mt\bigr),\quad
 R_{j\star}\pm T_{\star j}=\tfrac14e^{2jt}(\bar g\pm C).
\end{equation}
Consequently the data are interpolated by a function in $\mathcal S$ if and only if
$(\nu,C)$ is feasible at $t$.

\label{prop:spiral}
For every $t\ne0$, the data
\begin{equation}\label{eq:spiraldata}
 u=1-\frac1{2G},\quad c=-\frac1{2G},\quad \nu=\delta_c,\quad C=g\tanh t
\end{equation}
are feasible at $(\operatorname{arsinh} u,t)$, and $\ell_1=\upsilon_2=\upsilon_3=0$. On this
spectrum
\begin{equation}\label{eq:En}
 \frac{\ell_m}g=\frac{E_{m+1}(t)}G,\quad \frac{\upsilon_m}g=\frac{E_{m-1}(t)}G,\quad
 E_n(t)=\cosh nt+2G^2\cos n\omega,
\end{equation}
and for every $n\ge3$, $G^{n-2}E_n(t)$ is a polynomial in $G^2-1$ with
nonnegative coefficients, positive for $t\ne0$. The relation
$u=\sinh(t-\log q)$ on this curve is \eqref{eq:spiralpoly} with $\rho=e^t$.

\label{thm:classification}
Let $G_W=(1+\sqrt3)/2$, let $G_1\in(1.03329,1.03330)$ be the root of
$32G^3-36G^2+4G-1$, and let $G_a\in(1.02358,1.02359)$ be the root of
\begin{equation}\label{eq:Ha}
 \begin{aligned}
 H_a(G)={}&162529280000G^{12}-238685519872G^{10}+77668708352G^8\\
 &-6246545408G^6-58821872G^4+12933112G^2+229441 .
 \end{aligned}
\end{equation}
Then $V(t)=\operatorname{arsinh} u(\cosh t)$, where
\begin{equation}\label{eq:classification}
 u(G)=\begin{cases}
 u_5(G),&1\le G\le G_a,\\
 u_2(G),&G_a\le G\le G_1,\\
 1-(2G)^{-1},&G_1\le G\le G_W,\\
 u_1(G),&G_W\le G<\infty,
 \end{cases}
\end{equation}
and $u_1$, $u_2$, $u_5$ are the values of $u$ on the families $P_1$, $P_2$,
$P_5$. On $P_2$, $G_1=G(\zeta_1)$ and $G_a=G(\zeta_a)$, where $\zeta_1$ is the
real root of $\zeta^3-\zeta^2-2$ and $\zeta_a\in(1.6989,1.699)$ is a root of
the polynomial $N_{12}$ of degree twelve in Lemma~\ref{lem:p2ends}; at $G=1$ the central family reduces
to the three-cycle, $u=\frac12$, $x=-\frac12$, $p=d=0$. The branches are
unique within the parametrization of $P_2$ and the verified continuations of
$P_1$ and $P_5$, and their values agree at the endpoints. The function
$t\mapsto t-V(t)$ is continuous and strictly increasing, so
\begin{equation}\label{eq:scalarprescription}
 t-\operatorname{arsinh} u(\cosh t)=\log q
\end{equation}
has exactly one solution $t=T(q)$, and $\rho_{\rm HB}=e^{T(q)}$. At most two atoms are
needed.

\label{lem:angle}
For $\omega\in(0,\pi)$,
\begin{equation}\label{eq:Xi}
 \cot\Theta(\omega)=\frac{\Xi(\cos\omega)}{\sin\omega},\quad
 \Xi(c)=\frac{B^2-(1-\beta)^2-A^2+2A(1+\beta)c-4\beta c^2}{2B(1-\beta)} .
\end{equation}
The quadratic $\Xi$ is concave, $\Xi(1)<0$ and $\Xi(-1)<0$; consequently
$\Theta(\pi)=\pi$ and $\Theta(\omega)\to\pi$ as $\omega\to0$.

\label{thm:convex}
Let $c=\cos\omega$, $s_\omega=\sin\omega$, $A_1=-\Xi(1)>0$, $A_2=-\Xi(-1)>0$,
$X=A_1(1+c)^2$, $Y=A_2(1-c)^2$ and $\Xi=\Xi(c)$. Then
$\Theta''(\omega)=\mathsf W/\bigl(2s_\omega^5(1+\cot^2\Theta)^2\bigr)$ with
\begin{multline*}
 \mathsf W=\Xi(X-Y)^2+\Xi^2\bigl[X(3c+2)+Y(2-3c)\bigr]+2\Xi^3(1+c^2)+2\Xi(1-c^2)^2\\
 +A_1(1+c)^3(1-c)(2-c)+A_2(1-c)^3(1+c)(2+c),
\end{multline*}
and $\Theta''>0$ at every $\omega\in(0,\pi)$ with $\Theta(\omega)\le\pi/2$.

\label{thm:fan-conv}
Assume \eqref{eq:quad} and let $K\ge2$. If there are finitely many weights
$\lambda_n\ge0$, $n\in\Lambda_{\rm fan}(K)$, and $\gamma>0$ such that
\begin{multline}\label{eq:fanlag}
 \Xi(c)\Bigl[\sum_{m\ge0}\lambda_{mK+1}\bigl(1-T_{mK+1}(c)\bigr)+\sum_{m\ge1}\lambda_{-mK}\bigl(1-T_{mK}(c)\bigr)+\gamma\Bigr]\\
 <(1-c^2)\Bigl[\sum_{m\ge0}\lambda_{mK+1}U_{mK}(c)-\sum_{m\ge1}\lambda_{-mK}U_{mK-1}(c)\Bigr]\quad(-1\le c\le1),
\end{multline}
then $\rho<1$. The simplest case, $\lambda_1=1$ and $\lambda_{-K}=r\ge0$, is the
two-lag inequality
\begin{equation}\label{eq:twolag}
 \Xi(c)\bigl[(1-c)+r(1-T_K(c))+\gamma\bigr]<(1-c^2)\bigl(1-rU_{K-1}(c)\bigr)\quad(-1\le c\le1).
\end{equation}

\label{lem:energy}
Suppose \eqref{eq:strictcert} holds at the exponent $t$ with lags at most $M'$.
There are $K>0$ and an integer $w\ge M'+2$ such that for every segment and
$w\le i\le j\le n-w$,
\begin{equation}\label{eq:energy}
 \sum_{k=i}^j\mathsf b_k\le K(E_i+E_j),\quad \mathsf b_k=e^{-2kt}\lVert e_k\rVert^2,\quad
 E_k=\sum_{|l-k|\le w}\mathsf b_l .
\end{equation}

\label{lem:vmono}
For Polyak's tuning:
\begin{enumerate}[label=\textup{(\roman*)}]
\par\hangindent 40\p@ $(t,C)\mapsto(-t,-C)$ at fixed $(v,\nu)$ preserves feasibility;
\par\hangindent 40\p@ $(v,C)\mapsto(-v,-C)$ at fixed $(t,\nu)$ interchanges the lower and upper
constraints and preserves feasibility;
\par\hangindent 40\p@ if $(\nu,C)$ is feasible at $(v,t)$ and $0\le v'\le v$, then $(\nu,\theta C)$
with $\theta=\sinh v'/\sinh v$ is feasible at $(v',t)$.
\end{enumerate}
Consequently the set of $v$ feasible at $t$ is $[-V(t),V(t)]$, $V$ is even, and
$V\le\operatorname{arsinh}1$.

\label{lem:tailsharp}
For $c=\cos\omega\in[-1,1]$ and $u\in\mathbb R$,
$g(c)^2+(2u\sin\omega)^2=(1-c^2+u^2)^2$. Consequently, for every spectrum and
every $m\ge1$,
\begin{equation}\label{eq:tailsharp}
 \ell_m,\ \upsilon_m\ \ge\ (\bar g-|C|)\cosh mt-(\bar g+2u^2).
\end{equation}

\label{prop:spiralsub}
Let $q\in(0,1)$, let $t_{\rm sp}=\log\rho_{\rm sp}(\kappa)\ne0$, and let $G=\cosh t_{\rm sp}$.
If $G>G_W$ or $1<G<G_1$, then $\rho_{\rm HB}>\rho_{\rm sp}$.

\label{prop:strip}
Every point $(v,t)$ at which \eqref{eq:feasible} is feasible satisfies
\begin{equation}\label{eq:thresholdstrip}
 |v|\le|t|+\log\varphi,
\end{equation}
strictly if $t\ne0$. At $t=0$ the three-cycle $\nu=\delta_{-1/2}$, $C=0$, is
feasible at $v=\log\varphi$.

\label{lem:p2ends}
Let $\zeta_1$ be the real root of $\zeta^3-\zeta^2-2$, and let
\begin{align*}
 N_{12}={}&25\zeta^{12}-314\zeta^{11}+1764\zeta^{10}-6092\zeta^9+14988\zeta^8-28736\zeta^7\\
 &+44832\zeta^6-57472\zeta^5+59952\zeta^4-48736\zeta^3+28224\zeta^2-10048\zeta+1600 .
\end{align*}
Then $1.6956<\zeta_1<1.6957$, and $N_{12}$ has exactly one root $\zeta_a$ in
$\mathcal J=[1.6955,1.699]$, with $1.6989<\zeta_a<1.699$; both roots are simple.
Moreover:
\begin{enumerate}[label=\textup{(\alph*)}]
\par\hangindent 40\p@ $G(\zeta_1)=G_1$ and $u(\zeta_1)=1-1/(2G_1)$. With $G=G(\zeta)$,
\begin{gather*}
32G^3-36G^2+4G-1=\frac{(\zeta^3+2\zeta+4)(\zeta^3-\zeta^2-2)\,S_6}{16\zeta^3r_-^3},\\
u-1+\frac1{2G}=\frac{8(\zeta^3-\zeta^2-2)^2}{r_-r_+q_-q_+}\ \ge0,
\end{gather*}
with $S_6=\zeta^6-8\zeta^5-2\zeta^4+16\zeta^3+4\zeta^2-32\zeta-8$; the curve $P_2$
touches the spiral curve $u=1-1/(2G)$ at $\zeta_1$ and lies above it.
\par\hangindent 40\p@ $G_a:=G(\zeta_a)$ is the root of $H_a$ in $(1.02358,1.02359)$: $N_{12}$
divides the numerator of $H_a(G(\zeta))$.
\end{enumerate}

\label{lem:p5tail}
Let $0<h\le0.0236$, $t=\operatorname{arcosh}(1+h)$, and suppose that a two-atom spectrum
with the parameters \eqref{eq:blowup} satisfies
\begin{equation}\label{eq:centralbounds}
 \begin{gathered}
 0<\mathcal A<0.55,\quad -0.27<\mathcal B<0,\quad 0<P<3,\quad 0<D<2.2,\\
 u<\tfrac{11}{20},\quad \bar g>0.49,\quad \bar g-|C|>\tfrac14,\quad
 |g(x)-\tfrac12|<h,\quad |\bar g-\tfrac12|<2h,\\
 |2u\sin\omega_x-\tfrac{\sqrt3}2|<2h,\quad |\arccos x-\tfrac{2\pi}3|<\tfrac h3 .
 \end{gathered}
\end{equation}
Then $\ell_m,\upsilon_m>0$ for all $m\ge24$.

\label{lem:startupslack}
For $k\ge1$,
\begin{equation}\label{eq:startupslack}
 R_{0k}\mp T_{0k}=\mathsf a_\mp X^2+\operatorname{Re}(\mathsf b_\mp Z)+\mathsf c_\mp
 +\bigl(1-(-q^2)^{\lceil k/2\rceil}\bigr)^2,
\end{equation}
and $|T_{\star0}|=|\frac12\operatorname{Re}\Delta-\frac C4|$, $R_{0\star}=\frac14(5-|m+\Delta|^2)$. On
$F(\rho,q)=0$,
\begin{equation}\label{eq:startupidentities}
 \begin{gathered}
 g=\frac{2\rho(\rho^2-\rho+1)}{(\rho^2+1)^2}=\frac12-\frac{(\rho-1)^4}{2(\rho^2+1)^2},\\
 \operatorname{Re}\Delta=\frac q2\,\frac{\rho^2+2}{\rho^2+1}\le q,\quad
 |\Delta|^2=\frac{q^2}4\,\frac{\rho^4+4\rho^2+1}{\rho^2(\rho^2+1)} .
 \end{gathered}
\end{equation}
In particular $0<g\le\frac12$ and $|C|<\frac12$.

\label{lem:continuation}
Every $Y\in\mathcal K_H$ is the window $Y_H$ of an infinite segment, and hence of
an infinite $H$-segment.

\label{lem:prices}
Let $H\ge H_0$. For $0<\delta\le\delta_0$ there are linear functionals $\mathcal V_\delta$
on $\mathcal E_H$ with $\sup_\delta|\mathcal V_\delta|<\infty$ such that, with $t=T+\delta$:
\begin{enumerate}[label=\textup{(\roman*)}]
\par\hangindent 40\p@ for every $H$-segment and $H\le k\le n-2$,
$\mathcal V_\delta(Y_k)-e^{-2t}\mathcal V_\delta(Y_{k+1})\ge\delta\lVert e_{k-M_0}\rVert^2$;
\par\hangindent 40\p@ for every infinite $H$-segment and $k\ge H$,
$\mathcal V_\delta(Y_k)\ge\delta\sum_{i\ge0}e^{-2it}\lVert e_{k+i-M_0}\rVert^2$.
\end{enumerate}
In particular, $\mathcal V_\delta\ge0$ on $\mathcal K_H$.

\label{lem:exactprice}
Let $H\ge H_0$. There is a linear functional $\mathcal V_*$ on $\mathcal E_H$ such that
\begin{enumerate}[label=\textup{(\alph*)}]
\par\hangindent 40\p@ $\mathcal V_*\ge0$ on $\mathcal K_H$;
\par\hangindent 40\p@ $\mathcal V_*(Y_{k+1})\le e^{2T}\mathcal V_*(Y_k)$ for every $H$-segment and
$H\le k\le n-2$;
\par\hangindent 40\p@ if $(\nu,C)$ is $H$-feasible at $(T-\log q,T)$, the windows of its
stationary sequence at the exponent $T$ satisfy
$\mathcal V_*(Y_k)\ge\frac12e^{2(k-M_0)T}>0$ for $k\ge H$.
\end{enumerate}

\label{prop:single}
Let $\omega_0=2\pi j/k$ with $\gcd(j,k)=1$ and $1\le j<k/2$. At $t=0$ the pair
$(\delta_{\omega_0},0)$ is feasible if and only if $\Theta(\omega_0)\le\pi/k$.

\label{lem:Kmu}
If $a(r)=0$, that is, $x=(1-r)(1-\beta/r)$, then $H_r(c)=(1-c)K_\mu(c)$ with
\begin{align*}
K_\mu(c)={}&4\beta r^3c^2+2r\bigl(r^3(y-1)-\beta r^3+\beta r^2-2\beta r-\beta^2\bigr)c\\
&+r^5+r^4y-r^3y+r^3-\beta r^4+\beta r^3-\beta r^2y-\beta r^2-\beta ry+\beta r+\beta^2r^2+\beta^2,
\end{align*}
and $K_\mu(-1)=(\beta+r^2)(1+r)b(-r)$. If $b(-r)=0$, that is,
$y=(1+r)(1+\beta/r)$, then $H_r(c)=(1+c)K_L(c)$ with
\begin{align*}
K_L(c)={}&-4\beta r^3c^2+2r^2\bigl(\beta^2+3\beta+\beta r-\beta x-r^3\bigr)c\\
&+r^5-r^4x+2r^4+r^3x-r^3+\beta r^4-\beta r^3+\beta r^2x\\
&-3\beta r^2+\beta rx-\beta r-\beta^2r^2-2\beta^2r+\beta^2,
\end{align*}
and $K_L(1)=(\beta+r^2)(1-r)a(r)$.
